/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
/// The <t>PurchTable</t> table extension
/// </summary>
[ExtensionOf(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity))]
final class METPurchPurchaseOrderConfirmationLineEntity_Extension
{
}

Method.Source:
    /// <summary>
    /// Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        MetItemSiteSettingsSetup    metItemSiteSettingsSetup;

        select firstonly TempRcvLimit from metItemSiteSettingsSetup
            where metItemSiteSettingsSetup.ItemId == this.ItemNumber &&             
                  metItemSiteSettingsSetup.InventSiteId == this.ReceivingSiteId &&
                  metItemSiteSettingsSetup.TempRcvLimit != 0;

        if(!metItemSiteSettingsSetup.TempRcvLimit)
        {
            select firstonly TempRcvLimit from metItemSiteSettingsSetup
                where  metItemSiteSettingsSetup.ItemId == this.ItemNumber &&
                       metItemSiteSettingsSetup.TempRcvLimit != 0;
        }

        this.METPOLineTempRcvLimit = metItemSiteSettingsSetup.TempRcvLimit? metItemSiteSettingsSetup.TempRcvLimit: InventTable::find(this.ItemNumber).PdsBestBefore;

        next postload();
    }

    /// <summary>
    /// getPOLineCartonPerLayer method COC
    /// </summary>
    /// <returns> string value</returns>
    private static server str getPOLineCartonPerLayer()
    {
        str metCartonPerLayer;
        SysDictTable      metDictMetItemSiteSettingsSetup = new SysDictTable(tableNum(MetItemSiteSettingsSetup));
        str metItemId;
        str metSiteId;
        str metSqlQuery = 'SELECT TOP 1 %1 FROM %2 WHERE ((%2.%3 = %4 AND %2.%5 = %6) OR %2.%3 = %4) AND %2.%1 != 0';

        metItemId = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
                fieldStr(PurchLineAllVersions, itemid));

        metSiteId = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, InventDim),
                fieldStr(InventDim, InventSiteId));


        metCartonPerLayer = strFmt(@metSqlQuery,
                                metDictMetItemSiteSettingsSetup.fieldName(fieldNum(MetItemSiteSettingsSetup, CartonPerLayer), DbBackend::Sql),
                                metDictMetItemSiteSettingsSetup.name(DbBackend::Sql),
                                metDictMetItemSiteSettingsSetup.fieldName(fieldNum(MetItemSiteSettingsSetup, ItemId), DbBackend::Sql),
                                metItemId,
                                metDictMetItemSiteSettingsSetup.fieldName(fieldNum(MetItemSiteSettingsSetup, InventSiteId), DbBackend::Sql),
                                metSiteId);

        return metCartonPerLayer;
    }

