    /// <summary>
    /// getPOLineConfInventoryQty method COC
    /// </summary>
    /// <returns> string value</returns>
    private static server str getPOLineConfInventoryQty()
    {
        str                 metInventoryQty;
        SysDictTable        metDictPurchLine = new SysDictTable(tableNum(PurchLine));
        str                 metItemId;
        str                 metLineNum;
        str                 metPurchId;
        str                 metSqlQuery = 'SELECT TOP 1 %1 FROM %2 WHERE %2.%3 = %4 AND %2.%5 = %6 AND %2.%7 = %8';

        metPurchId = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
                        fieldStr(PurchLineAllVersions, purchId));

        metItemId = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
                        fieldStr(PurchLineAllVersions, itemid));

        metLineNum = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
                        fieldStr(PurchLineAllVersions, lineNumber));


        metInventoryQty = strFmt(@metSqlQuery,
                                metDictPurchLine.fieldName(fieldNum(PurchLine, QtyOrdered), DbBackend::Sql),
                                metDictPurchLine.name(DbBackend::Sql),
                                metDictPurchLine.fieldName(fieldNum(PurchLine, purchId), DbBackend::Sql),
                                metPurchId,
                                metDictPurchLine.fieldName(fieldNum(PurchLine, ItemId), DbBackend::Sql),
                                metItemId,
                                metDictPurchLine.fieldName(fieldNum(PurchLine, lineNumber), DbBackend::Sql),
                                metLineNum);

        return metInventoryQty;
    }

    /// <summary>
    /// getPOLineConfPurchGTIN method COC
    /// MPJ-28341-GTIN value that is being used for ITEM 13011 is incorrect
    /// </summary>
    /// <returns> string value</returns>
    private static server str getPOLineConfPurchGTIN()
    {
        str                 metBarcode;
        SysDictTable        metDictInventItemBarcode = new SysDictTable(tableNum(InventItemBarcode));
        str                 metItemId;
        str                 metUom;        
        str                 metSqlQuery = 'SELECT TOP 1 %1 FROM %2 WHERE %2.%3 = %4 AND %2.%5 = %6';
              

        metItemId = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
                        fieldStr(PurchLineAllVersions, itemid));
        
        metUom = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
                        fieldStr(PurchLineAllVersions,purchunit));
        
        metBarcode = strFmt(@metSqlQuery,
                            metDictInventItemBarcode.fieldName(fieldNum(InventItemBarcode, ItemBarCode), DbBackend::Sql),
                            metDictInventItemBarcode.name(DbBackend::Sql),            
                            metDictInventItemBarcode.fieldName(fieldNum(InventItemBarcode, ItemId), DbBackend::Sql),
                            metItemId,
                            metDictInventItemBarcode.fieldName(fieldNum(InventItemBarcode, UnitId), DbBackend::Sql),
                            metUom);

        return metBarcode;
    }

    /// <summary>
    /// getPOLinePromotionIHG method COC
    /// </summary>
    /// <returns> string value</returns>
    private static server str getPOLinePromotionIHG()
    {
        str                 metPOLinePromotionIHG;
        SysDictTable        metDictMETPurchLine = new SysDictTable(tableNum(METPurchLine));
        SysDictTable        metDictPurchLine = new SysDictTable(tableNum(PurchLine));
        str                 metItemId;
        str                 metLineNum;
        str                 metPurchId;
        str                 metSqlQuery = 'SELECT TOP 1 %1 FROM %2 JOIN %3 ON %2.%4 = %3.%5 WHERE %3.%6 = %7 AND %3.%8 = %9 AND %3.%10 = %11';

        metPurchId = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
                        fieldStr(PurchLineAllVersions, purchId));

        metItemId = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
                        fieldStr(PurchLineAllVersions, itemid));

        metLineNum = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
                        fieldStr(PurchLineAllVersions, lineNumber));


        metPOLinePromotionIHG = strFmt(@metSqlQuery,
                                        metDictMETPurchLine.fieldName(fieldNum(METPurchLine, PromotionIHG), DbBackend::Sql), //%1
                                        metDictMETPurchLine.name(DbBackend::Sql), //%2
                                        metDictPurchLine.name(DbBackend::Sql), //%3
                                        metDictMETPurchLine.fieldName(fieldNum(METPurchLine, PurchLine), DbBackend::Sql),//%4
                                        metDictPurchLine.fieldName(fieldNum(PurchLine, RecId), DbBackend::Sql),//%5
                                        metDictPurchLine.fieldName(fieldNum(PurchLine, purchId), DbBackend::Sql),//%6
                                        metPurchId,//%7
                                        metDictPurchLine.fieldName(fieldNum(PurchLine, ItemId), DbBackend::Sql),//%8
                                        metItemId,//%9
                                        metDictPurchLine.fieldName(fieldNum(PurchLine, lineNumber), DbBackend::Sql),//%10
                                        metLineNum);//%11

        return metPOLinePromotionIHG;
    }

